// Forge 3.0 consolidated foundry core (FDL3 -> FBC3).
// It creates revisioned, buildable Davis Ring-3 C++ sources plus manifests/tests.
static constexpr u32 W=900,H=600; static u32*pix; static u64 events,win; static bool dirty=true;
static char name[40]={0}, intent[180]={0}; static char lastDsl[960]={0}; static u32 nl=0,il=0; static int field=0,gen=0; static char status[96]="DESCRIBE A SMALL UTILITY, THEN GENERATE";
static u32 slen(const char*s){u32 n=0;while(s&&s[n])n++;return n;} static void cat(char*d,u32 cap,const char*s){u32 n=slen(d),i=0;while(s&&s[i]&&n+1<cap)d[n++]=s[i++];d[n]=0;}
static void num(char*out,u32 v){char t[12];u32 n=0;if(!v){out[0]='0';out[1]=0;return;}while(v&&n<11){t[n++]=(char)('0'+v%10);v/=10;}u32 z=0;while(n)out[z++]=t[--n];out[z]=0;}
static bool has(const char*s,const char*q){if(!s||!q)return false;for(u32 i=0;s[i];i++){u32 j=0;while(q[j]&&s[i+j]&&((s[i+j]|32)==(q[j]|32)))j++;if(!q[j])return true;}return false;}
static void rr(i32 x,i32 y,i32 w,i32 h,i32 r,u32 c){rect(pix,W,H,x+r,y,w-2*r,h,c);rect(pix,W,H,x,y+r,w,h-2*r,c);for(i32 yy=0;yy<r;yy++)for(i32 xx=0;xx<r;xx++){i32 dx=r-xx-1,dy=r-yy-1;if(dx*dx+dy*dy<=r*r){rect(pix,W,H,x+xx,y+yy,1,1,c);rect(pix,W,H,x+w-1-xx,y+yy,1,1,c);rect(pix,W,H,x+xx,y+h-1-yy,1,1,c);rect(pix,W,H,x+w-1-xx,y+h-1-yy,1,1,c);}}}
static void writeAll(i64 h,const char*s){if(h>0)sc(34,(u64)h,(u64)s,slen(s));}
static void sanitize(){if(!nl){cat(name,sizeof(name),"NewTool");nl=slen(name);}for(u32 i=0;i<nl;i++)if(!((name[i]>='A'&&name[i]<='Z')||(name[i]>='a'&&name[i]<='z')||(name[i]>='0'&&name[i]<='9')||name[i]=='_'))name[i]='_';}
#pragma pack(push,1)
struct ForgeProject{u32 magic,version,generation;char name[40];char intent[180];u32 digest;};
#pragma pack(pop)
static u32 projectDigest(const ForgeProject&q){u32 h=2166136261u;const u8*b=(const u8*)&q;for(u32 i=0;i<sizeof(q)-4;i++){h^=b[i];h*=16777619u;}return h;}
static void projectPath(char*out,u32 cap){out[0]=0;cat(out,cap,"/Home/Documents/");cat(out,cap,name);cat(out,cap,"_FORGE.PROJECT");}
static bool saveProject(){sanitize();ForgeProject q{};q.magic=0x334A5250;q.version=0x00040000;q.generation=(u32)gen;for(u32 i=0;i<39&&name[i];i++)q.name[i]=name[i];for(u32 i=0;i<179&&intent[i];i++)q.intent[i]=intent[i];q.digest=projectDigest(q);char path[128];projectPath(path,sizeof(path));i64 h=sc(32,(u64)path,2|4|8);if(h<=0)return false;bool ok=sc(34,(u64)h,(u64)&q,sizeof(q))==(i64)sizeof(q);sc(35,(u64)h);return ok;}
static bool loadProject(){sanitize();char path[128];projectPath(path,sizeof(path));i64 h=sc(32,(u64)path,1);if(h<=0)return false;ForgeProject q{};i64 n=sc(33,(u64)h,(u64)&q,sizeof(q));sc(35,(u64)h);if(n!=(i64)sizeof(q)||q.magic!=0x334A5250||q.version!=0x00040000||q.digest!=projectDigest(q))return false;for(u32 i=0;i<40;i++)name[i]=q.name[i];name[39]=0;for(u32 i=0;i<180;i++)intent[i]=q.intent[i];intent[179]=0;nl=slen(name);il=slen(intent);gen=(int)q.generation;return true;}
// Forge v2.0 constrained bytecode compiler + disposable validation VM.
// This is intentionally not x86 machine-code generation yet: Forge compiles a safe
// application plan to FBC1 bytecode, executes it in a bounded in-process sandbox,
// and only then records the generation as validated.
enum Op:u8 { OP_END=0, OP_WINDOW=1, OP_LABEL=2, OP_BUTTON=3, OP_COUNTER=4, OP_TEXT=5, OP_PERSIST=6, OP_INPUT=7, OP_LIST=8, OP_ACTION=9, OP_IF_INPUT=10, OP_CALC=11, OP_VAR=12, OP_SET=13, OP_ARITH=14, OP_COMPARE=15, OP_EVENT=16, OP_RECORD=17, OP_FUNC=18, OP_CALL=19, OP_BRANCH=20, OP_FILTER=21, OP_BOOL=22, OP_TABLE=23, OP_CLEAR=24, OP_SUB=25, OP_LAYOUT=26, OP_PANEL=27, OP_CHECKBOX=28, OP_DIALOG=29, OP_SCROLL=30, OP_SELECT=31, OP_NUMBER=32, OP_PROGRESS=33, OP_TABS=34, OP_STATUS=35 };
struct Program { u8 code[128]; u32 bytes; u32 budget; u32 requiredCaps; };
struct VmResult { bool ok; u32 steps; u32 windows; u32 controls; u32 stateCells; u32 fault; };
static Program lastProgram{}; static VmResult lastVm{}; static bool compilePass=false,sandboxPass=false,semanticPass=false,behaviorPass=false,scenarioPass=false,telemetryPass=false,livePass=false,regressionRejected=false; static u32 semanticFault=0,repairPasses=0,qualityScore=0,bestQuality=0,bestGeneration=0;
#pragma pack(push,1)
struct BestGeneration{u32 magic,version,generation,quality,bytes,budget,caps,digest;u8 code[128];};
#pragma pack(pop)
static u32 bestDigest(const BestGeneration&q){u32 h=2166136261u;const u8*b=(const u8*)&q;for(u32 i=0;i<sizeof(q)-4;i++){h^=b[i];h*=16777619u;}return h;}
static void bestPath(char*out,u32 cap){out[0]=0;cat(out,cap,"/Home/Documents/");cat(out,cap,name);cat(out,cap,"_FORGE.BEST");}
static bool loadBest(BestGeneration&q){char path[128];bestPath(path,sizeof(path));i64 h=sc(32,(u64)path,1);if(h<=0)return false;i64 n=sc(33,(u64)h,(u64)&q,sizeof(q));sc(35,(u64)h);if(n!=(i64)sizeof(q)||q.magic!=0x54534542||q.version!=0x00050000||q.bytes>128)return false;u32 d=q.digest;q.digest=0;bool ok=d==bestDigest(q);q.digest=d;return ok;}
static bool saveBest(const Program&pr,u32 generation,u32 quality){BestGeneration q{};q.magic=0x54534542;q.version=0x00050000;q.generation=generation;q.quality=quality;q.bytes=pr.bytes;q.budget=pr.budget;q.caps=pr.requiredCaps;for(u32 i=0;i<pr.bytes;i++)q.code[i]=pr.code[i];q.digest=0;q.digest=bestDigest(q);char path[128];bestPath(path,sizeof(path));i64 h=sc(32,(u64)path,2|4|8);if(h<=0)return false;bool ok=sc(34,(u64)h,(u64)&q,sizeof(q))==(i64)sizeof(q);sc(35,(u64)h);return ok;}
static constexpr u32 FORGE_RUNNER_SERVICE=4, MSG_RUN=0x46424331;
#pragma pack(push,1)
struct RunReq{u32 magic,bytes,budget,caps,testMask;char name[40];u8 code[128];};
#pragma pack(pop)
static u64 lastRunnerPid=0; static u32 lastRunDetail=0; static u32 moduleFaultRole=0xffffffffu,interactionFault=0;
static u32 candidateContractScore=0,baselineContractScore=0,baselineRunDetail=0; static bool differentialPass=true;

// v15 cumulative executable TESTS. Current intent contributes new tests, while
// every previously promoted test remains in a per-project regression baseline.
static u32 expectedTelemetry();
enum TestBit:u32{T_WINDOW=1u<<0,T_ENTER=1u<<1,T_POINTER=1u<<2,T_FOCUS=1u<<3,T_MULTISTEP=1u<<4,T_COHERENCE=1u<<5,T_CHECKBOX=1u<<6,T_SELECT=1u<<7,T_TABS=1u<<8};
#pragma pack(push,1)
struct TestBaseline{u32 magic,version,mask,generation,digest;};
#pragma pack(pop)
static u32 retainedTestMask=0,retainedTestGeneration=0;
static u32 testBaselineDigest(const TestBaseline&q){u32 h=2166136261u;const u8*b=(const u8*)&q;for(u32 i=0;i<sizeof(q)-4;i++){h^=b[i];h*=16777619u;}return h;}
static void testBaselinePath(char*out,u32 cap){out[0]=0;cat(out,cap,"/Home/Documents/");cat(out,cap,name);cat(out,cap,"_FORGE.TESTBASE");}
static bool loadTestBaseline(){retainedTestMask=0;retainedTestGeneration=0;char path[128];testBaselinePath(path,sizeof(path));i64 h=sc(32,(u64)path,1);if(h<=0)return false;TestBaseline q{};i64 n=sc(33,(u64)h,(u64)&q,sizeof(q));sc(35,(u64)h);if(n!=(i64)sizeof(q)||q.magic!=0x42545354||q.version!=0x000F0000)return false;u32 d=q.digest;q.digest=0;if(d!=testBaselineDigest(q))return false;retainedTestMask=q.mask;retainedTestGeneration=q.generation;return true;}
static bool saveTestBaseline(u32 mask,u32 generation){TestBaseline q{};q.magic=0x42545354;q.version=0x000F0000;q.mask=mask;q.generation=generation;q.digest=0;q.digest=testBaselineDigest(q);char path[128];testBaselinePath(path,sizeof(path));i64 h=sc(32,(u64)path,2|4|8);if(h<=0)return false;bool ok=sc(34,(u64)h,(u64)&q,sizeof(q))==(i64)sizeof(q);sc(35,(u64)h);if(ok){retainedTestMask=mask;retainedTestGeneration=generation;}return ok;}
static u32 currentTestMask(){u32 m=T_WINDOW;u32 e=expectedTelemetry();if(e&(1u<<1))m|=T_ENTER|T_FOCUS|T_MULTISTEP|T_COHERENCE;if(e&(1u<<7))m|=T_POINTER|T_COHERENCE;if(e&(1u<<16))m|=T_CHECKBOX|T_POINTER;if(e&(1u<<22))m|=T_SELECT|T_POINTER;if(e&(1u<<25))m|=T_TABS|T_POINTER;return m;}
static u32 executableTestMask(){return currentTestMask()|retainedTestMask;}
static bool promoteLive(const Program&pr){u64 pid=(u64)sc(SYS_SPAWN_ISOLATED,49);lastRunnerPid=pid;lastRunDetail=0;if(!pid)return false;u64 svc=0;u32 sid=0x1000u+(u32)pid;for(u32 tries=0;tries<600&&!svc;tries++){svc=(u64)sc(SYS_SERVICE,sid);if(!svc)sc(SYS_YIELD);}if(!svc)return false;RunReq q{};q.magic=0x33434246;q.bytes=pr.bytes;q.budget=pr.budget;q.caps=pr.requiredCaps;q.testMask=executableTestMask();for(u32 i=0;i<38&&name[i];i++)q.name[i]=name[i];for(u32 i=0;i<pr.bytes;i++)q.code[i]=pr.code[i];if(sc(SYS_IPC_SEND,svc,MSG_RUN,(u64)&q,sizeof(q))<0)return false;for(u32 tries=0;tries<1200;tries++){u64 r=(u64)sc(SYS_FORGE_RUN_QUERY,pid);u32 st=(u32)r;lastRunDetail=(u32)(r>>32);if(st==1)return true;if(st==2)return false;sc(SYS_YIELD);}lastRunDetail=3;return false;}

// v9 telemetry uses exact UI contracts instead of the old aggregate rich-UI bit.
// Bits 14..18 identify requested primitives; 19..21 prove their interaction routes.
static u32 expectedTelemetry(){u32 e=1u<<0;if(has(intent,"input")||has(intent,"note")||has(intent,"text")||has(intent,"list")||has(intent,"table")||has(intent,"inventory")||has(intent,"todo")||has(intent,"budget")||has(intent,"calculator"))e|=1u<<1;if(has(intent,"list")||has(intent,"table")||has(intent,"inventory")||has(intent,"todo")||has(intent,"database")||has(intent,"records"))e|=1u<<4;if(has(intent,"calculate")||has(intent,"calculator")||has(intent,"sum")||has(intent,"total")||has(intent,"budget")||has(intent,"cost"))e|=1u<<5;if(has(intent,"if ")||has(intent,"when")||has(intent,"threshold")||has(intent,"limit")||has(intent,"alert"))e|=1u<<6;if(has(intent,"dashboard")||has(intent,"form"))e|=(1u<<14)|(1u<<15);if(has(intent,"settings")||has(intent,"panel"))e|=1u<<15;if(has(intent,"checkbox")||has(intent,"toggle")||has(intent,"settings"))e|=(1u<<16)|(1u<<19);if(has(intent,"dialog")||has(intent,"confirm")||has(intent,"prompt"))e|=(1u<<17)|(1u<<20);if(has(intent,"scroll")||has(intent,"long list")||has(intent,"document"))e|=(1u<<18)|(1u<<21);if(has(intent,"select")||has(intent,"dropdown")||has(intent,"choose"))e|=(1u<<22)|(1u<<27);if(has(intent,"number")||has(intent,"numeric")||has(intent,"quantity"))e|=(1u<<23)|(1u<<28);if(has(intent,"progress")||has(intent,"percent")||has(intent,"completion"))e|=1u<<24;if(has(intent,"tabs")||has(intent,"tabbed"))e|=(1u<<25)|(1u<<29);if(has(intent,"status")||has(intent,"state indicator"))e|=1u<<26;return e;}
static bool validateTelemetry(){u32 e=expectedTelemetry();interactionFault=0;if((lastRunDetail&e)!=e){interactionFault=1;return false;}if(!(lastRunDetail&(1u<<8))){interactionFault=2;return false;}if((lastRunDetail&(1u<<2))&&(lastRunDetail&(1u<<7))&&!(lastRunDetail&(1u<<9))){interactionFault=3;return false;}bool expectsInput=(e&(1u<<1))!=0;if(expectsInput&&!(lastRunDetail&(1u<<11))){interactionFault=4;return false;}if(expectsInput&&!(lastRunDetail&(1u<<13))){interactionFault=5;return false;}if((lastRunDetail&(1u<<7))&&!(lastRunDetail&(1u<<12))){interactionFault=6;return false;}return true;}
static u32 popcount32(u32 v){u32 n=0;while(v){n+=v&1u;v>>=1;}return n;}
static u32 contractMask(){u32 m=expectedTelemetry()|(1u<<8);if(expectedTelemetry()&(1u<<1))m|=(1u<<11)|(1u<<13);if(expectedTelemetry()&(1u<<7))m|=(1u<<12);if((expectedTelemetry()&(1u<<2))&&(expectedTelemetry()&(1u<<7)))m|=1u<<9;if(expectedTelemetry()&(1u<<1))m|=1u<<30;if((expectedTelemetry()&(1u<<1))||(expectedTelemetry()&(1u<<7)))m|=1u<<31;return m;}
static u32 contractScore(u32 detail){u32 m=contractMask();return popcount32(detail&m);}
static bool differentialValidate(const BestGeneration*prior){candidateContractScore=contractScore(lastRunDetail);baselineContractScore=0;baselineRunDetail=0;if(!prior)return true;Program bp{};bp.bytes=prior->bytes;bp.budget=prior->budget;bp.requiredCaps=prior->caps;for(u32 i=0;i<bp.bytes&&i<128;i++)bp.code[i]=prior->code[i];u32 candidateDetail=lastRunDetail;bool ok=promoteLive(bp);baselineRunDetail=lastRunDetail;baselineContractScore=ok?contractScore(baselineRunDetail):0;lastRunDetail=candidateDetail;return candidateContractScore>=baselineContractScore;}
static bool emit(Program&pr,u8 op,u8 a=0,u8 b=0,u8 c=0){if(pr.bytes+4>sizeof(pr.code))return false;pr.code[pr.bytes++]=op;pr.code[pr.bytes++]=a;pr.code[pr.bytes++]=b;pr.code[pr.bytes++]=c;return true;}
static void dslReset(){lastDsl[0]=0;} static void dsl(const char*x){cat(lastDsl,sizeof(lastDsl),x);cat(lastDsl,sizeof(lastDsl),"\n");}
static void synthesizeDsl(){
 dslReset();dsl("FDL3");dsl("WINDOW");dsl("LABEL GENERATED_BY_FORGE");
 bool finance=has(intent,"budget")||has(intent,"expense")||has(intent,"finance")||has(intent,"money")||has(intent,"cost");
 bool list=has(intent,"inventory")||has(intent,"todo")||has(intent,"list")||has(intent,"tracker")||has(intent,"task")||has(intent,"catalog");
 bool math=has(intent,"calculator")||has(intent,"calculate")||has(intent,"math")||has(intent,"total")||has(intent,"sum");
 bool note=has(intent,"note")||has(intent,"text")||has(intent,"memo")||has(intent,"journal")||has(intent,"write");
 bool count=has(intent,"counter")||has(intent,"count")||has(intent,"tally")||has(intent,"score");
 bool table=has(intent,"table")||has(intent,"rows")||has(intent,"database")||has(intent,"records");
 bool filter=has(intent,"search")||has(intent,"filter")||has(intent,"find");
 bool conditional=has(intent,"alert")||has(intent,"limit")||has(intent,"threshold")||has(intent,"when")||has(intent,"if ");
 if(finance){dsl("VAR NUMBER TOTAL");dsl("INPUT AMOUNT");dsl("INPUT DESCRIPTION");dsl("RECORD TRANSACTION");if(table)dsl("TABLE TRANSACTIONS");dsl("FUNCTION ADD_TRANSACTION");dsl("EVENT ENTER ADD_RECORD");dsl("ARITH TOTAL ADD AMOUNT");if(conditional){dsl("COMPARE TOTAL GT 1000");dsl("IF TOTAL GT 1000 ELSE");}dsl("CALL ADD_TRANSACTION");dsl("BUTTON CLEAR");}
 else if(list||table){dsl("VAR NUMBER COUNT");dsl("INPUT ITEM");dsl("INPUT DETAIL");if(table)dsl("TABLE ITEMS");else dsl("LIST ITEMS");dsl("FUNCTION ADD_ITEM");dsl("EVENT ENTER ADD_ITEM");dsl("ARITH COUNT ADD 1");if(filter)dsl("FILTER ITEMS INPUT");if(conditional){dsl("COMPARE COUNT GT 100");dsl("IF COUNT GT 100 ELSE");}dsl("CALL ADD_ITEM");dsl("BUTTON CLEAR");}
 else if(math){dsl("VAR NUMBER TOTAL");dsl("INPUT NUMBER");dsl("FUNCTION CALCULATE");dsl("EVENT ENTER CALCULATE");dsl("ARITH TOTAL ADD INPUT");if(conditional){dsl("COMPARE TOTAL GT 100");dsl("IF TOTAL GT 100 ELSE");}dsl("CALL CALCULATE");dsl("BUTTON RESET");}
 else if(note){dsl("VAR TEXT LAST");dsl("INPUT NOTE");dsl("TEXT WORKSPACE");dsl("FUNCTION COMMIT");dsl("EVENT ENTER COMMIT");dsl("CALL COMMIT");}
 else if(count){dsl("VAR NUMBER COUNT");dsl("COUNTER");dsl("EVENT CLICK INCREMENT");if(conditional){dsl("COMPARE COUNT GT 100");dsl("IF COUNT GT 100 ELSE");}dsl("BUTTON RESET");}
 else {dsl("VAR TEXT STATUS");dsl("INPUT VALUE");dsl("EVENT ENTER COMMIT");dsl("LABEL GENERATED_UTILITY");dsl("BUTTON ACTION");}
 if(has(intent,"dashboard")||has(intent,"form")||has(intent,"settings")||has(intent,"panel")){dsl("LAYOUT COLUMN");dsl("PANEL MAIN");}
 if(has(intent,"checkbox")||has(intent,"toggle")||has(intent,"settings"))dsl("CHECKBOX ENABLED");
 if(has(intent,"dialog")||has(intent,"confirm")||has(intent,"prompt"))dsl("DIALOG CONFIRM");
 if(has(intent,"scroll")||has(intent,"long list")||has(intent,"document"))dsl("SCROLL MAIN");
 if(has(intent,"select")||has(intent,"dropdown")||has(intent,"choose"))dsl("SELECT OPTION");
 if(has(intent,"number")||has(intent,"numeric")||has(intent,"quantity"))dsl("NUMBER VALUE");
 if(has(intent,"progress")||has(intent,"percent")||has(intent,"completion"))dsl("PROGRESS VALUE");
 if(has(intent,"tabs")||has(intent,"tabbed"))dsl("TABS MAIN");
 if(has(intent,"status")||has(intent,"state indicator"))dsl("STATUS READY");
 dsl("END");
}
static bool lineeq(const char*p,u32 n,const char*q){u32 m=slen(q);if(n!=m)return false;for(u32 i=0;i<n;i++)if(p[i]!=q[i])return false;return true;}
static bool starts(const char*p,u32 n,const char*q){u32 m=slen(q);if(n<m)return false;for(u32 i=0;i<m;i++)if(p[i]!=q[i])return false;return true;}
static bool compileDsl(Program&pr){pr={};pr.budget=128;pr.requiredCaps=1|2;u32 pos=0,line=0;while(lastDsl[pos]){u32 st=pos;while(lastDsl[pos]&&lastDsl[pos]!='\n')pos++;u32 n=pos-st;const char*p=lastDsl+st;if(lastDsl[pos]=='\n')pos++;line++;if(line==1){if(!lineeq(p,n,"FDL3"))return false;continue;}if(lineeq(p,n,"WINDOW")){if(!emit(pr,OP_WINDOW,1))return false;}else if(starts(p,n,"LABEL ")){if(!emit(pr,OP_LABEL,lineeq(p+6,n-6,"GENERATED_BY_FORGE")?1:2))return false;}else if(lineeq(p,n,"COUNTER")){if(!emit(pr,OP_COUNTER,1))return false;}else if(starts(p,n,"INPUT ")){u8 id=1;if(starts(p,n,"INPUT DETAIL")||starts(p,n,"INPUT DESCRIPTION"))id=2;else if(starts(p,n,"INPUT NOTE"))id=3;if(!emit(pr,OP_INPUT,id))return false;}else if(starts(p,n,"LIST ")){if(!emit(pr,OP_LIST,1))return false;}else if(starts(p,n,"VAR NUMBER ")){if(!emit(pr,OP_VAR,1,1))return false;}else if(starts(p,n,"VAR TEXT ")){if(!emit(pr,OP_VAR,2,1))return false;}else if(starts(p,n,"RECORD ")){if(!emit(pr,OP_RECORD,1))return false;}else if(starts(p,n,"FUNCTION ")){if(!emit(pr,OP_FUNC,1))return false;}else if(starts(p,n,"CALL ")){if(!emit(pr,OP_CALL,1))return false;}else if(starts(p,n,"IF ")){if(!emit(pr,OP_BRANCH,1,1))return false;}else if(starts(p,n,"FILTER ")){if(!emit(pr,OP_FILTER,1,1))return false;}else if(starts(p,n,"EVENT ENTER ADD_ITEM")){if(!emit(pr,OP_EVENT,1,1))return false;}else if(starts(p,n,"EVENT ENTER ADD_RECORD")){if(!emit(pr,OP_EVENT,1,2))return false;}else if(starts(p,n,"EVENT ENTER CALCULATE")){if(!emit(pr,OP_EVENT,1,3))return false;}else if(starts(p,n,"EVENT ENTER COMMIT")){if(!emit(pr,OP_EVENT,1,4))return false;}else if(starts(p,n,"EVENT CLICK INCREMENT")){if(!emit(pr,OP_EVENT,2,1))return false;}else if(starts(p,n,"ARITH ")){if(!emit(pr,OP_ARITH,1,starts(p,n,"ARITH TOTAL ADD INPUT")?2:1))return false;}else if(starts(p,n,"COMPARE ")){if(!emit(pr,OP_COMPARE,1,1))return false;}else if(lineeq(p,n,"BUTTON RESET")){if(!emit(pr,OP_BUTTON,2))return false;}else if(lineeq(p,n,"BUTTON CLEAR")){if(!emit(pr,OP_ACTION,2))return false;}else if(lineeq(p,n,"BUTTON ACTION")){if(!emit(pr,OP_ACTION,4))return false;}else if(lineeq(p,n,"TEXT WORKSPACE")){if(!emit(pr,OP_TEXT,1))return false;}else if(starts(p,n,"VAR BOOL ")){if(!emit(pr,OP_BOOL,1,1))return false;}else if(starts(p,n,"TABLE ")){if(!emit(pr,OP_TABLE,1))return false;}else if(lineeq(p,n,"CLEAR STATE")){if(!emit(pr,OP_CLEAR,1))return false;}else if(starts(p,n,"SUB ")){if(!emit(pr,OP_SUB,1,1))return false;}else if(starts(p,n,"LAYOUT ")){if(!emit(pr,OP_LAYOUT,1,1))return false;}else if(starts(p,n,"PANEL ")){if(!emit(pr,OP_PANEL,1,1))return false;}else if(starts(p,n,"CHECKBOX ")){if(!emit(pr,OP_CHECKBOX,1,1))return false;}else if(starts(p,n,"DIALOG ")){if(!emit(pr,OP_DIALOG,1,1))return false;}else if(starts(p,n,"SCROLL ")){if(!emit(pr,OP_SCROLL,1,1))return false;}else if(starts(p,n,"SELECT ")){if(!emit(pr,OP_SELECT,1,1))return false;}else if(starts(p,n,"NUMBER ")){if(!emit(pr,OP_NUMBER,1,1))return false;}else if(starts(p,n,"PROGRESS ")){if(!emit(pr,OP_PROGRESS,1,1))return false;}else if(starts(p,n,"TABS ")){if(!emit(pr,OP_TABS,1,1))return false;}else if(starts(p,n,"STATUS ")){if(!emit(pr,OP_STATUS,1,1))return false;}else if(lineeq(p,n,"END")){return emit(pr,OP_END);}else return false;}return false;}
static bool writeDsl(const char*nm,const char*g){char bp[128]="/Home/Documents/";cat(bp,sizeof(bp),nm);cat(bp,sizeof(bp),"_g");cat(bp,sizeof(bp),g);cat(bp,sizeof(bp),".forge");i64 h=sc(32,(u64)bp,2|4);if(h<=0)return false;writeAll(h,lastDsl);sc(35,(u64)h);return true;}
static VmResult runSandbox(const Program&pr){VmResult r{};u32 ip=0;while(ip+3<pr.bytes&&r.steps++<pr.budget){u8 op=pr.code[ip],a=pr.code[ip+1];ip+=4;switch(op){case OP_END:r.ok=r.windows==1&&r.controls>0;return r;case OP_WINDOW:if(r.windows||a!=1){r.fault=1;return r;}r.windows++;r.controls++;break;case OP_LABEL:r.controls++;break;case OP_BUTTON:r.controls++;break;case OP_COUNTER:r.stateCells++;r.controls++;break;case OP_TEXT:r.stateCells++;r.controls++;break;case OP_PERSIST:if(!(pr.requiredCaps&8)){r.fault=3;return r;}r.controls++;break;case OP_INPUT:r.stateCells++;r.controls++;break;case OP_LIST:r.stateCells++;r.controls++;break;case OP_ACTION:r.controls++;break;case OP_IF_INPUT:r.controls++;break;case OP_CALC:r.stateCells++;r.controls++;break;case OP_VAR:r.stateCells++;break;case OP_SET:r.stateCells++;break;case OP_ARITH:r.stateCells++;r.controls++;break;case OP_COMPARE:r.controls++;break;case OP_EVENT:r.controls++;break;case OP_RECORD:r.stateCells++;r.controls++;break;case OP_FUNC:r.controls++;break;case OP_CALL:r.controls++;break;case OP_BRANCH:r.controls++;break;case OP_FILTER:r.controls++;break;case OP_BOOL:r.stateCells++;break;case OP_TABLE:r.stateCells++;r.controls++;break;case OP_CLEAR:r.stateCells++;r.controls++;break;case OP_SUB:r.stateCells++;r.controls++;break;case OP_LAYOUT:r.controls++;break;case OP_PANEL:r.controls++;break;case OP_CHECKBOX:r.stateCells++;r.controls++;break;case OP_DIALOG:r.controls++;break;case OP_SCROLL:r.controls++;break;default:r.fault=2;return r;}}r.fault=4;return r;}
static bool writeBytecode(const char*nm,const char*g,const Program&pr){char bp[128]="/Home/Documents/";cat(bp,sizeof(bp),nm);cat(bp,sizeof(bp),"_g");cat(bp,sizeof(bp),g);cat(bp,sizeof(bp),".fbc");i64 h=sc(32,(u64)bp,2|4);if(h<=0)return false;const char magic[4]={'F','B','C','3'};sc(34,(u64)h,(u64)magic,4);sc(34,(u64)h,(u64)&pr.bytes,4);sc(34,(u64)h,(u64)&pr.budget,4);sc(34,(u64)h,(u64)&pr.requiredCaps,4);sc(34,(u64)h,(u64)pr.code,pr.bytes);sc(35,(u64)h);return true;}
static u32 checksum(const Program&pr){u32 h=2166136261u;for(u32 i=0;i<pr.bytes;i++){h^=pr.code[i];h*=16777619u;}return h;}
static bool programHas(const Program&pr,u8 wanted){for(u32 i=0;i+3<pr.bytes;i+=4)if(pr.code[i]==wanted)return true;return false;}
static bool semanticValidate(const Program&pr){semanticFault=0;if(!programHas(pr,OP_WINDOW)){semanticFault=1;return false;}if((has(intent,"inventory")||has(intent,"todo")||has(intent,"list")||has(intent,"tracker"))&&!(programHas(pr,OP_LIST)||programHas(pr,OP_TABLE))){semanticFault=2;return false;}if((has(intent,"table")||has(intent,"database")||has(intent,"records"))&&!programHas(pr,OP_TABLE)){semanticFault=3;return false;}if((has(intent,"search")||has(intent,"filter")||has(intent,"find"))&&!programHas(pr,OP_FILTER)){semanticFault=4;return false;}if((has(intent,"calculator")||has(intent,"calculate")||has(intent,"math")||has(intent,"total")||has(intent,"sum")||has(intent,"budget")||has(intent,"expense"))&&!programHas(pr,OP_ARITH)){semanticFault=5;return false;}if((has(intent,"note")||has(intent,"text")||has(intent,"memo")||has(intent,"journal")||has(intent,"write"))&&!programHas(pr,OP_TEXT)){semanticFault=6;return false;}if((has(intent,"counter")||has(intent,"count")||has(intent,"tally")||has(intent,"score"))&&!programHas(pr,OP_COUNTER)){semanticFault=7;return false;}if((has(intent,"alert")||has(intent,"limit")||has(intent,"threshold")||has(intent,"when")||has(intent,"if "))&&!(programHas(pr,OP_COMPARE)&&programHas(pr,OP_BRANCH))){semanticFault=8;return false;}return true;}
static void insertBeforeEnd(const char*x){char old[960]={0};for(u32 i=0;i<959&&lastDsl[i];i++)old[i]=lastDsl[i];dslReset();u32 p=0;while(old[p]){u32 st=p;while(old[p]&&old[p]!='\n')p++;u32 n=p-st;if(old[p]=='\n')p++;if(n==3&&old[st]=='E'&&old[st+1]=='N'&&old[st+2]=='D')break;char line[128]={0};u32 z=0;while(z<n&&z<127){line[z]=old[st+z];z++;}line[z]=0;dsl(line);}dsl(x);dsl("END");}
static bool repairSemanticPlan(){repairPasses=0;for(u32 pass=0;pass<4;pass++){Program candidate{};if(!compileDsl(candidate))return false;VmResult vr=runSandbox(candidate);if(!vr.ok)return false;if(semanticValidate(candidate)){lastProgram=candidate;lastVm=vr;return true;}repairPasses++;switch(semanticFault){case 1: insertBeforeEnd("WINDOW");break;case 2: insertBeforeEnd("LIST ITEMS");break;case 3: insertBeforeEnd("TABLE ITEMS");break;case 4: insertBeforeEnd("FILTER ITEMS INPUT");break;case 5: insertBeforeEnd("ARITH TOTAL ADD INPUT");break;case 6: insertBeforeEnd("TEXT WORKSPACE");break;case 7: insertBeforeEnd("COUNTER");break;case 8: insertBeforeEnd("COMPARE COUNT GT 100");insertBeforeEnd("IF COUNT GT 100 ELSE");break;default:return false;}}return false;}
static bool behaviorValidate(const Program&pr){bool hasEvent=programHas(pr,OP_EVENT),hasAction=programHas(pr,OP_ACTION)||programHas(pr,OP_BUTTON)||programHas(pr,OP_CALL);if((programHas(pr,OP_INPUT)||programHas(pr,OP_COUNTER)||programHas(pr,OP_LIST)||programHas(pr,OP_TABLE))&&!hasEvent)return false;if((programHas(pr,OP_LIST)||programHas(pr,OP_TABLE))&&!hasAction)return false;if(programHas(pr,OP_BRANCH)&&!programHas(pr,OP_COMPARE))return false;if(programHas(pr,OP_FILTER)&&!(programHas(pr,OP_LIST)||programHas(pr,OP_TABLE)))return false;return true;}
static bool scenarioValidate(const Program&pr){if(!behaviorValidate(pr))return false;u32 interactive=0,stateful=0,mutating=0;for(u32 i=0;i+3<pr.bytes;i+=4){u8 op=pr.code[i];if(op==OP_INPUT||op==OP_BUTTON)interactive++;if(op==OP_VAR||op==OP_COUNTER||op==OP_LIST||op==OP_TABLE||op==OP_TEXT)stateful++;if(op==OP_ARITH||op==OP_CLEAR||op==OP_ACTION||op==OP_CALL)mutating++;}if(interactive&&!programHas(pr,OP_EVENT)&&!programHas(pr,OP_ACTION))return false;if((programHas(pr,OP_LIST)||programHas(pr,OP_TABLE))&&!stateful)return false;if(programHas(pr,OP_EVENT)&&!mutating&&!programHas(pr,OP_COUNTER)&&!programHas(pr,OP_TEXT))return false;return true;}
static bool targetedRuntimeRepair(){u32 need=expectedTelemetry()&~lastRunDetail;moduleFaultRole=0xffffffffu;if(!need&&interactionFault==0)return false;
 // Attribute the failure before patching: MODEL=0, VIEW=1, EVENTS=2.
 if(need&((1u<<4)|(1u<<5)|(1u<<6)))moduleFaultRole=0;
 else if(need&((1u<<0)|(1u<<1)|(1u<<14)|(1u<<15)|(1u<<16)|(1u<<17)|(1u<<18)|(1u<<19)|(1u<<20)|(1u<<21)))moduleFaultRole=1;
 else moduleFaultRole=2;
 if(need&(1u<<1))insertBeforeEnd("INPUT VALUE");
 if(need&(1u<<4))insertBeforeEnd("TABLE ITEMS");
 if(need&(1u<<5))insertBeforeEnd("ARITH TOTAL ADD INPUT");
 if(need&(1u<<6)){insertBeforeEnd("COMPARE COUNT GT 100");insertBeforeEnd("IF COUNT GT 100 ELSE");}
 if(need&(1u<<14))insertBeforeEnd("LAYOUT COLUMN");
 if(need&(1u<<15))insertBeforeEnd("PANEL MAIN");
 if(need&((1u<<16)|(1u<<19)))insertBeforeEnd("CHECKBOX ENABLED");
 if(need&((1u<<17)|(1u<<20)))insertBeforeEnd("DIALOG CONFIRM");
 if(need&((1u<<18)|(1u<<21)))insertBeforeEnd("SCROLL MAIN");
 if(need&((1u<<22)|(1u<<27)))insertBeforeEnd("SELECT OPTION");
 if(need&((1u<<23)|(1u<<28)))insertBeforeEnd("NUMBER VALUE");
 if(need&(1u<<24))insertBeforeEnd("PROGRESS VALUE");
 if(need&((1u<<25)|(1u<<29)))insertBeforeEnd("TABS MAIN");
 if(need&(1u<<26))insertBeforeEnd("STATUS READY");
 // Interaction faults are repaired in EVENTS without regenerating MODEL/VIEW.
 if(interactionFault==4)insertBeforeEnd("EVENT ENTER COMMIT");
 if(interactionFault==6)insertBeforeEnd("ACTION ADD");
 Program candidate{};if(!compileDsl(candidate))return false;VmResult vr=runSandbox(candidate);if(!vr.ok||!semanticValidate(candidate)||!behaviorValidate(candidate)||!scenarioValidate(candidate))return false;lastProgram=candidate;lastVm=vr;repairPasses++;return true;}
struct ModuleLine{u32 seq;u8 role;char text[80];}; static ModuleLine moduleLines[48]; static u32 moduleLineCount=0; static u32 moduleDigest=0;
static u8 moduleRole(const char*p,u32 n){if(starts(p,n,"VAR ")||starts(p,n,"RECORD ")||starts(p,n,"LIST ")||starts(p,n,"TABLE ")||lineeq(p,n,"COUNTER"))return 0;if(starts(p,n,"EVENT ")||starts(p,n,"FUNCTION ")||starts(p,n,"CALL ")||starts(p,n,"ARITH ")||starts(p,n,"COMPARE ")||starts(p,n,"IF ")||starts(p,n,"FILTER ")||starts(p,n,"SUB ")||starts(p,n,"CLEAR "))return 2;return 1;}
static bool buildModuleGraph(){moduleLineCount=0;moduleDigest=2166136261u;u32 pos=0,seq=0;while(lastDsl[pos]){u32 st=pos;while(lastDsl[pos]&&lastDsl[pos]!='\n')pos++;u32 n=pos-st;if(lastDsl[pos]=='\n')pos++;if(!n)continue;if(moduleLineCount>=48||n>=79)return false;ModuleLine&ml=moduleLines[moduleLineCount++];ml.seq=seq++;ml.role=moduleRole(lastDsl+st,n);for(u32 i=0;i<n;i++){ml.text[i]=lastDsl[st+i];moduleDigest^=(u8)ml.text[i];moduleDigest*=16777619u;}ml.text[n]=0;moduleDigest^='\n';moduleDigest*=16777619u;}return moduleLineCount>0;}
static bool linkModules(char*out,u32 cap){if(!out||cap<8)return false;out[0]=0;for(u32 seq=0;seq<moduleLineCount;seq++){bool found=false;for(u32 i=0;i<moduleLineCount;i++)if(moduleLines[i].seq==seq){cat(out,cap,moduleLines[i].text);cat(out,cap,"\n");found=true;break;}if(!found)return false;}return true;}
static bool moduleLinkValidate(){if(!buildModuleGraph())return false;char linked[960];if(!linkModules(linked,sizeof(linked)))return false;u32 i=0;while(linked[i]&&lastDsl[i]&&linked[i]==lastDsl[i])i++;if(linked[i]!=lastDsl[i])return false;Program linkedProgram{};char saved[960];for(u32 j=0;j<sizeof(saved);j++)saved[j]=lastDsl[j];for(u32 j=0;j<sizeof(lastDsl);j++)lastDsl[j]=linked[j];bool ok=compileDsl(linkedProgram);for(u32 j=0;j<sizeof(lastDsl);j++)lastDsl[j]=saved[j];if(!ok||linkedProgram.bytes!=lastProgram.bytes)return false;for(u32 j=0;j<linkedProgram.bytes;j++)if(linkedProgram.code[j]!=lastProgram.code[j])return false;return true;}
static bool writeModules(const char*nm,const char*g){if(!moduleLinkValidate())return false;const char*mods[]={"MODEL","VIEW","EVENTS","TESTS"};for(u32 m=0;m<4;m++){char bp[128]="/Home/Documents/";cat(bp,sizeof(bp),nm);cat(bp,sizeof(bp),"_g");cat(bp,sizeof(bp),g);cat(bp,sizeof(bp),"_");cat(bp,sizeof(bp),mods[m]);cat(bp,sizeof(bp),".fmod");i64 h=sc(32,(u64)bp,2|4|8);if(h<=0)return false;writeAll(h,"FORGE16.0 MODULE\nPROJECT: ");writeAll(h,nm);writeAll(h,"\nROLE: ");writeAll(h,mods[m]);writeAll(h,"\nLINK: SEQUENCE-PRESERVING / FAIL-CLOSED\n");if(m<3){for(u32 i=0;i<moduleLineCount;i++)if(moduleLines[i].role==m){writeAll(h,"FDL3> ");writeAll(h,moduleLines[i].text);writeAll(h,"\n");}}else{writeAll(h,"ASSERT WINDOW_PRESENT\nASSERT BUDGET_TERMINATES\nASSERT INTENT_TELEMETRY\nASSERT EVENT_STATE_TRANSITION_WHEN_INTERACTIVE\nASSERT ENTER_SEQUENCE_WHEN_INPUT\nASSERT POINTER_ROUTE_WHEN_ACTION\nASSERT FOCUS_ROUTE_WHEN_INPUT\nASSERT REGRESSION_NOT_WORSE_THAN_BEST\nASSERT SAME_CONTRACT_DIFFERENTIAL_NOT_WORSE\nASSERT MULTISTEP_STATEFUL_SEQUENCE\nASSERT STATE_COHERENCE_AFTER_SEQUENCE\nTEST WINDOW_BOOT\nTEST ENTER_NONEMPTY_MUTATES_STATE\nTEST POINTER_ACTION_MUTATES_STATE\nTEST INPUT_FOCUS_ROUTE\nTEST MULTISTEP_TRANSACTION_SEQUENCE\nTEST STATE_COHERENCE_CHECKPOINT\nTEST CHECKBOX_TOGGLE_WHEN_PRESENT\nTEST SELECT_ADVANCE_WHEN_PRESENT\nTEST TAB_SWITCH_WHEN_PRESENT\nASSERT ALL_RETAINED_PROJECT_TESTS\nASSERT NEW_TESTS_APPEND_ONLY_ON_PROMOTION\n");}sc(35,(u64)h);}return true;}
static u32 scoreProgram(const Program&pr){u32 q=10;if(compilePass)q+=15;if(sandboxPass)q+=15;if(semanticPass)q+=20;if(behaviorPass)q+=15;if(scenarioPass)q+=10;if(livePass)q+=10;if(telemetryPass)q+=5;if(repairPasses>0&&q>repairPasses*2)q-=repairPasses*2;return q>100?100:q;}
// v11: bounded multi-variant evolution. Variants are compiled and exercised in
// isolated ForgeRunner processes against the same intent contract. Ties prefer
// the smaller bytecode image so evolution does not grow programs gratuitously.
static u32 variantCount=0,winningVariant=0,winningVariantScore=0,winningModuleRole=3,moduleMutationWins[3]={0,0,0};
static bool evaluateCurrentVariant(Program&out,u32&score){
 Program pr{}; if(!compileDsl(pr))return false;
 VmResult vr=runSandbox(pr); if(!vr.ok)return false;
 if(!semanticValidate(pr)||!behaviorValidate(pr)||!scenarioValidate(pr))return false;
 if(!promoteLive(pr))return false;
 if(!validateTelemetry())return false;
 u32 contracts=contractScore(lastRunDetail);
 // Contract satisfaction dominates; compactness is only a tie-break component.
 score=contracts*1024u+(128u-pr.bytes);
 out=pr; return true;
}
static u32 evolutionEpochs=0,evolutionCandidates=0;
static void moduleMutation(u32 role,u32 epoch,u32 variant){
 // Mutations are deliberately role-scoped: MODEL changes state/data declarations,
 // VIEW changes presentation primitives, EVENTS changes event/action behavior.
 if(role==0){
  if(variant==1&&!has(lastDsl,"VAR NUMBER"))insertBeforeEnd("VAR NUMBER TOTAL");
  else if(variant==2&&!has(lastDsl,"BOOL"))insertBeforeEnd("BOOL ENABLED");
 }else if(role==1){
  if(variant==1&&!has(lastDsl,"STATUS READY"))insertBeforeEnd("STATUS READY");
  else if(variant==2&&!has(lastDsl,"PANEL MAIN"))insertBeforeEnd("PANEL MAIN");
 }else{
  if(variant==1&&!has(lastDsl,"EVENT ENTER"))insertBeforeEnd("EVENT ENTER COMMIT");
  else if(variant==2&&!has(lastDsl,"ACTION"))insertBeforeEnd("ACTION ADD");
 }
 // Epoch-specific diversity stays inside the selected module family.
 if(role==1&&epoch==2&&(has(intent,"list")||has(intent,"table")||has(intent,"document"))&&!has(lastDsl,"SCROLL MAIN"))insertBeforeEnd("SCROLL MAIN");
 if(role==2&&epoch==2&&(has(intent,"alert")||has(intent,"threshold"))&&!has(lastDsl,"COMPARE")){insertBeforeEnd("COMPARE COUNT GT 100");insertBeforeEnd("IF COUNT GT 100 ELSE");}
}
static bool evolveVariants(){
 moduleMutationWins[0]=moduleMutationWins[1]=moduleMutationWins[2]=0;winningModuleRole=3;
 char seed[960]={0},epochBestDsl[960]={0};for(u32 i=0;i<959&&lastDsl[i];i++)seed[i]=lastDsl[i];
 Program epochBest{};u32 epochBestScore=0;bool any=false;variantCount=0;winningVariant=0;evolutionEpochs=0;evolutionCandidates=0;
 // Three bounded epochs. The winner of each epoch becomes the seed for the next,
 // allowing several generations of improvement in one Forge operation.
 for(u32 epoch=0;epoch<3;epoch++){
  char roundSeed[960]={0};for(u32 i=0;i<960;i++)roundSeed[i]=seed[i];
  bool roundFound=false;Program roundBest{};u32 roundBestScore=0,roundWinner=0;char roundBestDsl[960]={0};
  for(u32 v=0;v<3;v++){
   for(u32 i=0;i<960;i++)lastDsl[i]=roundSeed[i];
   u32 role=epoch%3; // epoch 0 MODEL, 1 VIEW, 2 EVENTS
   if(v)moduleMutation(role,epoch,v);
   Program candidate{};u32 score=0;variantCount++;evolutionCandidates++;
   if(evaluateCurrentVariant(candidate,score)&&(!roundFound||score>roundBestScore||(score==roundBestScore&&candidate.bytes<roundBest.bytes))){
    roundFound=true;roundBest=candidate;roundBestScore=score;roundWinner=v;for(u32 i=0;i<960;i++)roundBestDsl[i]=lastDsl[i];
   }
  }
  if(!roundFound)break;
  evolutionEpochs++;any=true;epochBest=roundBest;epochBestScore=roundBestScore;winningVariant=roundWinner;winningModuleRole=epoch%3;if(roundWinner&&winningModuleRole<3)moduleMutationWins[winningModuleRole]++;
  for(u32 i=0;i<960;i++){seed[i]=roundBestDsl[i];epochBestDsl[i]=roundBestDsl[i];}
 }
 if(!any){for(u32 i=0;i<960;i++)lastDsl[i]=seed[i];return false;}
 for(u32 i=0;i<960;i++)lastDsl[i]=epochBestDsl[i];lastProgram=epochBest;winningVariantScore=epochBestScore;
 if(!promoteLive(lastProgram)||!validateTelemetry())return false;
 lastVm=runSandbox(lastProgram);compilePass=true;sandboxPass=lastVm.ok;semanticPass=semanticValidate(lastProgram);
 behaviorPass=semanticPass&&behaviorValidate(lastProgram);scenarioPass=behaviorPass&&scenarioValidate(lastProgram);
 livePass=scenarioPass;telemetryPass=livePass;return telemetryPass;
}
static void writeLineage(const char*nm,const char*g){char bp[128]="/Home/Documents/";cat(bp,sizeof(bp),nm);cat(bp,sizeof(bp),"_g");cat(bp,sizeof(bp),g);cat(bp,sizeof(bp),"_LINEAGE.txt");i64 h=sc(32,(u64)bp,2|4|8);if(h<=0)return;writeAll(h,"FORGE 17.0 CUMULATIVE REGRESSION LINEAGE\nPROJECT: ");writeAll(h,nm);writeAll(h,"\nGENERATION: ");writeAll(h,g);writeAll(h,"\nBOUNDED EPOCHS COMPLETED: ");char n[12];num(n,evolutionEpochs);writeAll(h,n);writeAll(h,"\nCANDIDATES EXERCISED: ");num(n,evolutionCandidates);writeAll(h,n);writeAll(h,"\nWINNING FINAL VARIANT: ");num(n,winningVariant);writeAll(h,n);writeAll(h,"\nWINNING CONTRACT SCORE: ");num(n,winningVariantScore);writeAll(h,n);writeAll(h,"\nMODULE MUTATION WIN COUNTS (MODEL/VIEW/EVENTS): ");num(n,moduleMutationWins[0]);writeAll(h,n);writeAll(h,"/");num(n,moduleMutationWins[1]);writeAll(h,n);writeAll(h,"/");num(n,moduleMutationWins[2]);writeAll(h,n);writeAll(h,"\nCURRENT TEST MASK: ");num(n,currentTestMask());writeAll(h,n);writeAll(h,"\nRETAINED TEST MASK: ");num(n,retainedTestMask);writeAll(h,n);writeAll(h,"\nCUMULATIVE EXECUTABLE TEST MASK: ");num(n,executableTestMask());writeAll(h,n);writeAll(h,"\nRETAINED BASELINE GENERATION: ");num(n,retainedTestGeneration);writeAll(h,n);writeAll(h,"\nSELECTION: CONTRACT SATISFACTION FIRST; SMALLER FBC3 BREAKS TIES\nREGRESSION: FINAL WINNER MUST STILL PASS RETAINED-BEST DIFFERENTIAL GATE\n");sc(35,(u64)h);}
static void writeHistory(const char*nm,const char*g,const Program&pr){char bp[128]="/Home/Documents/";cat(bp,sizeof(bp),nm);cat(bp,sizeof(bp),"_g");cat(bp,sizeof(bp),g);cat(bp,sizeof(bp),"_HISTORY.txt");i64 h=sc(32,(u64)bp,2|4|8);if(h<=0)return;writeAll(h,"FORGE 17.0 GENERATION SNAPSHOT\nNAME: ");writeAll(h,nm);writeAll(h,"\nGENERATION: ");writeAll(h,g);writeAll(h,"\nINTENT: ");writeAll(h,intent);writeAll(h,"\nFDL3:\n");writeAll(h,lastDsl);writeAll(h,"SEMANTIC TEST: ");writeAll(h,semanticPass?"PASS":"FAIL");writeAll(h,"\n");sc(35,(u64)h);}
