static u32 hashName32(const char*s){u32 h=2166136261u;for(;*s;s++){h^=(u8)*s;h*=16777619u;}return h?h:1;}
static u32 registryDigest(const InstalledPackage&q){u32 h=2166136261u;const u8*b=(const u8*)&q;u32 n=sizeof(q)-128+q.bytes;for(u32 i=0;i<n;i++){if(i>=20&&i<24)continue;h^=b[i];h*=16777619u;}return h;}
